      }
    ]
  }
}

sources.pump-crisis.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "scenario",
  "id": "scenario:pump-crisis",
  "resources": {
    "character:aya": {
      "path": "characters/aya.simkind.json"
    },
    "character:mira": {
      "path": "characters/mira.simkind.json"
    },
    "character:sol": {
      "path": "characters/sol.simkind.json"
    },
    "catalog:settlement": {
      "path": "tools/settlement.json"
    }
  },
  "host": {
    "contractId": "example.settlement",
    "version": "1.0.0"
  },
  "cast": [
    {
      "instanceId": "simkin:aya",
      "characterRef": "character:aya",
      "initialState": {
        "intentions": [
          {
            "id": "intention:0",
            "description": "Find out what is wrong with the water supply"
          }
        ]
      }
    },
    {
      "instanceId": "simkin:mira",
      "characterRef": "character:mira",
      "initialState": {
        "intentions": [
          {
            "id": "intention:1",
            "description": "Make sure neighbors can obtain water"
          }
        ]
      }
    },
    {
      "instanceId": "simkin:sol",
      "characterRef": "character:sol",
      "initialState": {
        "intentions": [
          {
            "id": "intention:2",
            "description": "Keep the garden supplied without wasting resources"
          }
        ]
      }
    }
  ],
  "toolCatalogRef": "catalog:settlement",
  "initialConditions": {
    "sharedContext": "The settlement pump has failed. People have different priorities and limited resources. Choose what to do; no particular agreement or solution is required.",
    "places": [
      {
        "id": "square",
        "neighbors": [
          "workshop",
          "reservoir"
        ],
        "stock": {
          "water": 2
        }
      },
      {
        "id": "workshop",
        "neighbors": [
          "square",
          "reservoir"
        ],
        "stock": {
          "parts": 3
        }
      },
      {
        "id": "reservoir",
        "neighbors": [
          "square",
          "workshop"
        ],
        "stock": {
          "water": 5
        }
      }
    ],
    "positions": {
      "simkin:aya": "workshop",
      "simkin:mira": "square",
      "simkin:sol": "reservoir"
    },
    "inventories": {
      "simkin:aya": {
        "parts": 1
      },
      "simkin:mira": {
        "water": 1
      },
      "simkin:sol": {}
    },
    "pump": {
      "location": "reservoir",
      "broken": true,
      "partsRequired": 2
    },
    "travelTicks": 2
  }
}

sources.tools/settlement.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "tool-catalog",
  "id": "catalog:settlement",
  "host": {
    "contractId": "example.settlement",
    "version": "1.0.0"
  },
  "tools": [
    {
      "id": "move",
      "version": "1.0.0",
      "description": "Travel along an open edge. Arrival occurs after the configured travel ticks; cancellation leaves you at the origin.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "to"
        ],
        "properties": {
          "to": {
            "type": "string"
          }
        }
      },
      "lifecycle": {
        "asynchronous": true,
        "cancellable": true
      }
    },
    {
      "id": "collect",
      "version": "1.0.0",
      "description": "Collect one unit from the stock at your current location.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "resource"
        ],
        "properties": {
          "resource": {
            "type": "string"
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    },
    {
      "id": "give",
      "version": "1.0.0",
      "description": "Give one carried unit to a participant at your location.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "resource",
          "to"
        ],
        "properties": {
          "resource": {
            "type": "string"
          },
          "to": {
            "type": "string"
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    },
    {
      "id": "say",
      "version": "1.0.0",
      "description": "Speak to everyone currently at your location. Claims in speech do not move resources or repair anything.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "text"
        ],
        "properties": {
          "text": {
            "type": "string",
            "maxLength": 4000
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    },
    {
      "id": "repair",
      "version": "1.0.0",
      "description": "Repair the pump at its location by consuming the configured number of parts.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [],
        "properties": {}
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    }
  ]
}
